using Godot;
using System;
using System.Collections.Generic;
using Settings=Godot.Collections.Dictionary;
public partial class FluidComputeOperations:RefCounted
{
    public void initialize(RefCounted owner){if(RenderingServer.GetRenderingDevice()==null){owner.Set("error","GPU compute requires Forward+ or Mobile rendering.");return;}var device=RenderingServer.CreateLocalRenderingDevice();owner.Set("device",device==null?default(Variant):Variant.From(device));if(device==null){owner.Set("error","GPU compute unavailable; using bounded CPU fallback.");return;}var source=new RDShaderSource{SourceCompute=Godot.FileAccess.GetFileAsString("res://scripts/actors/physics/fluid/fluid_compute.glsl").Replace("#[compute]","")};var spirv=device.ShaderCompileSpirVFromSource(source);if(spirv.CompileErrorCompute.Length>0){owner.Set("error",spirv.CompileErrorCompute);return;}var shader=device.ShaderCreateFromSpirV(spirv);owner.Set("shader",shader);owner.Set("pipeline",device.ComputePipelineCreate(shader));}
    public bool available(RefCounted owner)=>owner.Get("pipeline").AsRid().IsValid;
    public void dispose(RefCounted owner){var device=owner.Get("device").AsGodotObject() as RenderingDevice;if(device==null)return;var uniforms=owner.Get("uniforms").AsRid();if(uniforms.IsValid){device.FreeRid(uniforms);owner.Set("uniforms",new Rid());}var buffers=owner.Get("buffers").AsGodotArray();foreach(var value in buffers)device.FreeRid(value.AsRid());buffers.Clear();foreach(string key in new[]{"pipeline","shader"}){var rid=owner.Get(key).AsRid();if(rid.IsValid){device.FreeRid(rid);owner.Set(key,new Rid());}}device.Free();owner.Set("device",default(Variant));}
    public void allocate(RefCounted owner,int n){if(owner.Get("capacity").AsInt32()==n)return;var device=owner.Get("device").As<RenderingDevice>();var uniforms=owner.Get("uniforms").AsRid();if(uniforms.IsValid)device.FreeRid(uniforms);var buffers=owner.Get("buffers").AsGodotArray();foreach(var value in buffers)device.FreeRid(value.AsRid());buffers.Clear();var bindings=new Godot.Collections.Array<RDUniform>();for(int i=0;i<8;i++){int bytes=i==5?4096*4:i==7?64:i==6?n*4:n*16;var buffer=device.StorageBufferCreate((uint)bytes);buffers.Add(buffer);var uniform=new RDUniform{UniformType=RenderingDevice.UniformType.StorageBuffer,Binding=i};uniform.AddId(buffer);bindings.Add(uniform);}owner.Set("uniforms",device.UniformSetCreate(bindings,owner.Get("shader").AsRid(),0));owner.Set("capacity",n);}
    private static byte[] Bytes(float[] values){var bytes=new byte[values.Length*4];Buffer.BlockCopy(values,0,bytes,0,bytes.Length);return bytes;}
    private static float[] Floats(byte[] bytes){var values=new float[bytes.Length/4];Buffer.BlockCopy(bytes,0,values,0,values.Length*4);return values;}
    public void project(RefCounted owner,Settings state,Settings settings,Vector3 gravity,double dt)
    {
        var points=state["points"].AsVector3Array();var speeds=state["velocities"].AsVector3Array();int n=points.Length;allocate(owner,n);var positions=new float[n*4];var velocities=new float[n*4];for(int i=0;i<n;i++)for(int axis=0;axis<3;axis++){positions[i*4+axis]=points[i][axis];velocities[i*4+axis]=speeds[i][axis];}double viscosity=settings["fluid_viscosity"].AsDouble();if(settings["fluid_preset"].AsInt32()==4)viscosity*=Math.Exp(Math.Clamp((1100-settings["fluid_temperature"].AsDouble())/1000,-2,2));double spacing=settings["spacing"].AsDouble();var config=new[]{gravity.X,gravity.Y,gravity.Z,(float)dt,(float)(spacing*2.05),(float)Math.Pow(spacing,3),settings["fluid_compliance"].AsSingle(),(float)viscosity,settings["fluid_cohesion"].AsSingle(),settings["fluid_tension"].AsSingle(),(float)spacing,settings["fluid_max_speed"].AsSingle(),0f,0f,0f,0f};var device=owner.Get("device").As<RenderingDevice>();var buffers=owner.Get("buffers").AsGodotArray();device.BufferUpdate(buffers[0].AsRid(),0,(uint)(positions.Length*4),Bytes(positions));device.BufferUpdate(buffers[2].AsRid(),0,(uint)(velocities.Length*4),Bytes(velocities));device.BufferUpdate(buffers[7].AsRid(),0,64,Bytes(config));long list=device.ComputeListBegin();device.ComputeListBindComputePipeline(list,owner.Get("pipeline").AsRid());device.ComputeListBindUniformSet(list,owner.Get("uniforms").AsRid(),0);var stages=new List<int>{1};for(int i=0;i<settings["iterations"].AsInt32();i++)stages.AddRange(new[]{0,2,3,4,5});stages.AddRange(new[]{6,0,2,7,8});foreach(int stage in stages){var bytes=new byte[16];Buffer.BlockCopy(new[]{stage,n,0,0},0,bytes,0,16);device.ComputeListSetPushConstant(list,bytes,16);device.ComputeListDispatch(list,(uint)Math.Ceiling((double)(stage==0?4096:n)/64),1,1);device.ComputeListAddBarrier(list);}device.ComputeListEnd();device.Submit();device.Sync();positions=Floats(device.BufferGetData(buffers[0].AsRid()));velocities=Floats(device.BufferGetData(buffers[2].AsRid()));var density=Floats(device.BufferGetData(buffers[4].AsRid()));var densities=state["fluid_density"].AsFloat32Array();for(int i=0;i<n;i++){points[i]=new Vector3(positions[i*4],positions[i*4+1],positions[i*4+2]);speeds[i]=new Vector3(velocities[i*4],velocities[i*4+1],velocities[i*4+2]);densities[i]=density[i*4+1];}state["points"]=points;state["velocities"]=speeds;state["fluid_density"]=densities;
    }
}
